"""Tests for the vendored RIFE 4.x IFNet arch + loader (CPU, random weights).

The state dicts here come from `layouts.py`, which transcribes the key names and
shapes of the PUBLISHED checkpoints from the files themselves -- never from
`IFNet.state_dict()`. That direction matters: a fixture generated by the module
under test accepts whatever layout the module happens to implement, which is
exactly how a loader that rejected every real checkpoint passed its tests. Real
weights, when the maintainer has any, are covered by
`test_loads_real_checkpoints_from_models_dir`.

Forward passes assert shape/finiteness, NOT interpolation semantics: random
weights carry no meaningful flow, so t=0 is not close to frame0.
"""

from pathlib import Path

import pytest

torch = pytest.importorskip("torch")

from tests.vendor.rife.layouts import (
    ENCODER_LAYOUT,
    NARROW_ENCODER_BLOCKS,
    NARROW_NO_ENCODER_BLOCKS,
    REAL_ENCODER_BLOCKS,
    REAL_NO_ENCODER_BLOCKS,
    head_style_encoder_layout,
    real_layout,
    state_dict_for,
)
from vendor.rife.ifnet import IFNet
from vendor.rife.inference import interpolate, pad_dims
from vendor.rife.loader import SUPPORTED_FAMILY, load_ifnet

REAL_CHECKPOINT_DIRS = ("models/vfi", "models/video_interpolation/rife")


def _pair(h=64, w=64):
    torch.manual_seed(0)
    return torch.rand(1, 3, h, w), torch.rand(1, 3, h, w)


def _narrow(with_encoder):
    specs = NARROW_ENCODER_BLOCKS if with_encoder else NARROW_NO_ENCODER_BLOCKS
    return IFNet(specs, (16, 4) if with_encoder else None).eval()


# -- the published layouts load ----------------------------------------------

def test_loader_accepts_rife46_layout():
    state = state_dict_for(real_layout(REAL_NO_ENCODER_BLOCKS, with_encoder=False))

    model = load_ifnet(state, "cpu")

    assert model.num_blocks == 4
    assert model.encode is None
    assert model.mask_is_residual is True


def test_loader_accepts_feature_encoder_layout():
    state = state_dict_for(real_layout(REAL_ENCODER_BLOCKS, with_encoder=True))

    model = load_ifnet(state, "cpu")

    assert model.num_blocks == 4
    assert model.encode is not None
    # Two weighted layers named `encode.0`/`encode.1`, 3 -> 16 -> 4 channels.
    assert [type(m).__name__ for m in model.encode] == ["Conv2d", "ConvTranspose2d"]
    assert tuple(model.encode[0].weight.shape) == ENCODER_LAYOUT["encode.0.weight"]
    assert tuple(model.encode[1].weight.shape) == ENCODER_LAYOUT["encode.1.weight"]
    assert model.mask_is_residual is False


@pytest.mark.parametrize("blocks,with_encoder,n_tensors", [
    (REAL_NO_ENCODER_BLOCKS, False, 120),
    (REAL_ENCODER_BLOCKS, True, 124),
])
def test_transcribed_layout_matches_published_tensor_count(blocks, with_encoder, n_tensors):
    # 120 / 124 are the tensor counts of the real rife-4.6 and rife47/rife49
    # files; a fixture drifting from the published layout trips here first.
    assert len(real_layout(blocks, with_encoder)) == n_tensors


def test_loader_derives_block_widths_from_the_checkpoint():
    state = state_dict_for(real_layout(REAL_ENCODER_BLOCKS, with_encoder=True))

    model = load_ifnet(state, "cpu")

    for idx, (in_planes, c) in enumerate(REAL_ENCODER_BLOCKS):
        block = getattr(model, f"block{idx}")
        assert block.conv0[0][0].in_channels == in_planes
        assert block.conv0[1][0].out_channels == c


def test_loader_strips_module_and_flownet_prefixes():
    state = state_dict_for(real_layout(REAL_ENCODER_BLOCKS, with_encoder=True))
    prefixed = {("module.flownet." + k): v for k, v in state.items()}

    model = load_ifnet(prefixed, "cpu")

    assert model.num_blocks == 4 and model.encode is not None


def test_loader_reads_nested_state_dict_key():
    state = state_dict_for(real_layout(REAL_NO_ENCODER_BLOCKS, with_encoder=False))

    model = load_ifnet({"state_dict": state}, "cpu")

    assert model.num_blocks == 4


# -- layouts that are NOT this family are refused, not mis-built --------------

def test_loader_rejects_head_style_encoder():
    # The rife4.10+ line ships a multi-scale `Head` encoder (encode.cnn0..cnn3)
    # and a different forward; it must be refused, not silently loaded.
    state = state_dict_for({
        **real_layout(REAL_ENCODER_BLOCKS, with_encoder=False),
        **head_style_encoder_layout(),
    })

    with pytest.raises(ValueError, match="encode"):
        load_ifnet(state, "cpu")


def test_loader_rejects_unknown_checkpoint():
    with pytest.raises(ValueError) as exc:
        load_ifnet({"foo.weight": torch.zeros(1)}, "cpu")
    assert "rife" in str(exc.value).lower() or SUPPORTED_FAMILY in str(exc.value)


# -- real weights, when the maintainer has them ------------------------------

def test_loads_real_checkpoints_from_models_dir():
    files = [
        path
        for directory in REAL_CHECKPOINT_DIRS
        for pattern in ("*.pth", "*.safetensors")
        for path in sorted(Path(directory).glob(pattern))
    ]
    if not files:
        pytest.skip(f"no RIFE checkpoint present under {REAL_CHECKPOINT_DIRS}")

    i0, i1 = _pair()
    for path in files:
        model = load_ifnet(path, "cpu")
        mid = interpolate(model, i0, i1, 0.5, 1.0)
        assert mid.shape == (1, 3, 64, 64), path
        assert torch.isfinite(mid).all(), path


# -- forward / inference plumbing --------------------------------------------

@pytest.mark.parametrize("with_encoder", [False, True])
def test_forward_shape_and_finite(with_encoder):
    i0, i1 = _pair()

    mid = interpolate(_narrow(with_encoder), i0, i1, 0.5, 1.0)

    assert mid.shape == (1, 3, 64, 64)
    assert torch.isfinite(mid).all()


@pytest.mark.parametrize("t", [0.1, 0.25, 0.5, 0.75, 0.9])
def test_timestep_range_stays_finite_and_shaped(t):
    i0, i1 = _pair()

    mid = interpolate(_narrow(False), i0, i1, t, 1.0)

    assert mid.shape == (1, 3, 64, 64)
    assert torch.isfinite(mid).all()
    assert float(mid.min()) >= 0.0 - 1e-4


def test_padding_round_trip_non_multiple_input():
    # A size that is not a multiple of the RIFE padding lattice must be padded
    # for inference and cropped back to the exact input size.
    i0, i1 = _pair(h=70, w=100)

    mid = interpolate(_narrow(False), i0, i1, 0.5, 1.0)

    assert mid.shape == (1, 3, 70, 100)


def test_pad_dims_multiples():
    assert pad_dims(64, 64, 1.0) == (128, 128)
    assert pad_dims(64, 64, 0.5) == (256, 256)
    ph, pw = pad_dims(1080, 1920, 0.5)
    assert ph % 256 == 0 and pw % 256 == 0
    assert ph >= 1080 and pw >= 1920


def test_flow_scale_half_runs():
    i0, i1 = _pair(h=128, w=128)

    mid = interpolate(_narrow(False), i0, i1, 0.5, 0.5)

    assert mid.shape == (1, 3, 128, 128)
    assert torch.isfinite(mid).all()


def test_state_dict_round_trip_is_bit_identical():
    model = _narrow(True)
    reloaded = load_ifnet(model.state_dict(), "cpu")
    i0, i1 = _pair()

    assert torch.allclose(
        interpolate(model, i0, i1, 0.5, 1.0),
        interpolate(reloaded, i0, i1, 0.5, 1.0),
        atol=1e-6,
    )


# -- per-generation mask semantics -------------------------------------------

def test_mask_policy_follows_the_encoder_generation():
    # rife46 accumulates each block's mask residual, rife47-49 replace it. The
    # two are only distinguishable by the feature encoder's presence, so the
    # loader has to derive the policy rather than default one way.
    no_encoder = load_ifnet(state_dict_for(real_layout(REAL_NO_ENCODER_BLOCKS, False)), "cpu")
    encoder = load_ifnet(state_dict_for(real_layout(REAL_ENCODER_BLOCKS, True)), "cpu")

    assert no_encoder.mask_is_residual is True
    assert encoder.mask_is_residual is False


def test_mask_policy_changes_the_output():
    # Keeps the policy from decaying into a flag nothing reads.
    model = _narrow(True)
    i0, i1 = _pair()

    replaced = interpolate(model, i0, i1, 0.5, 1.0)
    model.mask_is_residual = True
    accumulated = interpolate(model, i0, i1, 0.5, 1.0)

    assert not torch.allclose(replaced, accumulated, atol=1e-5)


# -- warp -------------------------------------------------------------------

def test_warp_fp16_matches_input_dtype():
    from vendor.rife.warp import warp

    inp = torch.rand(1, 3, 32, 32, dtype=torch.float16)
    flow = torch.rand(1, 2, 32, 32, dtype=torch.float16)

    out = warp(inp, flow)

    assert out.dtype == torch.float16
    assert out.shape == inp.shape


def test_warp_grid_cache_keyed_by_dtype():
    import importlib

    warp_mod = importlib.import_module("vendor.rife.warp")

    inp32 = torch.rand(1, 3, 16, 16)
    flow32 = torch.rand(1, 2, 16, 16)
    warp_mod.warp(inp32, flow32)
    warp_mod.warp(inp32.half(), flow32.half())

    dtypes = {k[1] for k in warp_mod.backwarp_tenGrid if k[2] == str(flow32.size())}
    assert {"torch.float32", "torch.float16"} <= dtypes
